package de.androidcrypto.android_hce_emulate_a_creditcard;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import org.junit.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Per-scheme golden-trace tests: replay one full tap (SELECT PPSE, SELECT AID,
 * GPO, READ RECORDs, GENERATE AC, GET DATA 9F36) against each profile's static
 * fixtures through {@link EmvCardEmulatorCore#simulateTap} and assert the
 * golden contract: correct AID routing, PDOL capture, UN echo, AFL-listed
 * reads with fixture presence, AC template presence, TAP-OK.
 *
 * <p>Research fixtures only: all C-APDUs below come from the repo's own sample
 * reader logs / PDOL contracts; all PANs are EMVCo test profiles.
 */
public class EmvGoldenTraceTest {

    private static byte[] h(String hex) {
        int n = hex.length();
        byte[] out = new byte[n / 2];
        for (int i = 0; i < n; i += 2) {
            out[i / 2] = (byte) ((Character.digit(hex.charAt(i), 16) << 4)
                    + Character.digit(hex.charAt(i + 1), 16));
        }
        return out;
    }

    private static final String PPSE_SELECT = "00A404000E325041592E5359532E444446303100";
    private static final String VISA_AID_SELECT = "00A4040007A000000003101000";
    private static final String MC_AID_SELECT = "00A4040007A000000004101000";
    private static final String AMEX_AID_SELECT = "00A4040005A00000002500";
    private static final String DISCOVER_AID_SELECT = "00A4040005A00000015200";

    // Visa PDOL values from the sample reader log (33B: 9F66..9F37).
    private static final String VISA_GPO_DATA =
            "270000000000000010000000000000000978000000000009782303010038393031";

    private static void assertTapOk(String scheme, List<String> transcript) {
        StringBuilder log = new StringBuilder();
        for (String line : transcript) {
            log.append(line).append('\n');
        }
        boolean ok = false;
        for (String line : transcript) {
            if (line.startsWith("TAP-OK " + scheme)) {
                ok = true;
            }
            if (line.startsWith("FAIL")) {
                fail(scheme + " golden tap failed:\n" + log);
            }
        }
        assertTrue(scheme + " tap did not reach TAP-OK:\n" + log, ok);
    }

    @Test
    public void visa_goldenTap() {
        Map<String, byte[]> records = new HashMap<String, byte[]>();
        records.put("2/3", h(""));
        records.put("2/4", h("70078F01099F320103"));
        records.put("2/5", h(""));
        records.put("2/6", h("702E9F4701035A0841111111111111115F3401005F24032502285F280208269F6E04207000009F690701C1B626881600"));
        List<String> transcript = EmvCardEmulatorCore.simulateTap(
                "visa",
                h("6F2B840E325041592E5359532E4444463031A519BF0C1661144F07A00000000310109F0A080001050100000000"),
                h("6F5D8407A0000000031010A5525010564953412044454249542020202020208701029F38189F66049F02069F03069F1A0295055F2A029A039C019F37045F2D02656EBF0C1A9F5A0531082608269F0A080001050100000000BF6304DF200180"),
                h(""),
                records,
                h("771282021980940C080101001001010120010200"),
                0x03AA,
                PPSE_SELECT, VISA_AID_SELECT,
                new String[]{VISA_GPO_DATA},
                new String[]{"00B2031400", "00B2041400", "00B2051400", "00B2061400"},
                "00000000000000010000000000000000978000000000009782303010038393031");
        assertTapOk("visa", transcript);
    }

    @Test
    public void mastercard_goldenTap() {
        // Wire SFI numbering: AFL bytes 0x08/0x10/0x20 = SFI 1/2/4
        // (the sample-log labels SFI 8/10/20 are the pre-shift P2 bytes).
        Map<String, byte[]> records = new HashMap<String, byte[]>();
        records.put("1/1", h("70759F6C0200019F6206000000000F009F63060000000000FE563435353535353535353535343434345E202F5E323430333232313237393433323930303030303030303030303030303030309F6401029F65020F009F660200FE9F6B135555555555554444D24032212794329000000F9F670102"));
        records.put("2/1", h(""));
        records.put("4/1", h(""));
        records.put("4/2", h(""));
        // Mastercard AID advertises no PDOL; the sample reader sends empty GPO data.
        // Golden READs use wire P2 bytes: 00B2010800 (SFI 1), 00B2011000 (SFI 2),
        // 00B2012000 / 00B2022000 (SFI 4).
        List<String> transcript = EmvCardEmulatorCore.simulateTap(
                "mastercard",
                h("6F3C840E325041592E5359532E4444463031A52ABF0C2761254F07A000000004101050104465626974204D6173746572436172648701019F0A0400010101"),
                h("6F528407A0000000041010A54750104465626974204D6173746572436172649F12104465626974204D6173746572436172648701019F1101015F2D046465656EBF0C119F0A04000101019F6E0702800000303000"),
                h("772282021980940C0801010010010101200102009F360200019F26080000000000000000"),
                records,
                h("7712820297809408080101001001010120010200"),
                0x0001,
                PPSE_SELECT, MC_AID_SELECT,
                new String[]{""},
                new String[]{"00B2010800", "00B2011000", "00B2012000", "00B2022000"},
                null);
        assertTapOk("mastercard", transcript);
    }

    @Test
    public void amex_goldenTap() {
        // Golden READ set mirrors the generic 7712 fixture AFL (SFI 1/1, SFI 2/1).
        Map<String, byte[]> records = new HashMap<String, byte[]>();
        records.put("1/1", h("701B5A08378282246310005F3401019F0702FFC09F0D05B450840000"));
        records.put("2/1", h("700E9F6C0200019F6206000000000000"));
        // Amex PDOL: 9F66(4) 9F02(6) 9F03(6) 9F1A(2) 95(5) 9F37(4) = 27B values.
        // AFL 08010100 10010100 -> SFI 1/1, SFI 2/1 (generic 7712 fixture):
        // the golden READ set mirrors what the fixture advertises.
        List<String> transcript = EmvCardEmulatorCore.simulateTap(
                "amex",
                h("6F37840E325041592E5359532E4444463031A525BF0C2261204F05A000000025500D416D65782054657374436172648701019F0A0400010101"),
                h("6F2F8405A000000025A526500D416D65782054657374436172648701019F38119F66049F02069F03069F1A0295059F3704"),
                h("7712820219809408080101001001010120010200"),
                records,
                h("7712820297809408080101001001010120010200"),
                0x0001,
                PPSE_SELECT, AMEX_AID_SELECT,
                new String[]{"000000000000000000000000000009780000000000A1B2C3D4"},
                new String[]{"00B2010C00", "00B2011400"},
                null);
        assertTapOk("amex", transcript);
    }

    @Test
    public void discover_goldenTap() {
        // Golden READ set mirrors the generic 7712 fixture AFL (SFI 1/1, SFI 2/1).
        Map<String, byte[]> records = new HashMap<String, byte[]>();
        records.put("1/1", h("70235A0860111111111111175F34010157136011111111111117D230302112794329000000"));
        records.put("2/1", h("700E9F6C0200019F6206000000000000"));
        List<String> transcript = EmvCardEmulatorCore.simulateTap(
                "discover",
                h("6F3B840E325041592E5359532E4444463031A529BF0C2661244F05A0000001525011446973636F7665722054657374436172648701019F0A0400010101"),
                h("6F338405A000000152A52A5011446973636F7665722054657374436172648701019F38119F66049F02069F03069F1A0295059F3704"),
                h("7712820219809408080101001001010120010200"),
                records,
                h("7712820297809408080101001001010120010200"),
                0x0001,
                PPSE_SELECT, DISCOVER_AID_SELECT,
                new String[]{"000000000000000000000000000009780000000000D4E5F607"},
                new String[]{"00B2010C00", "00B2011400"},
                null);
        assertTapOk("discover", transcript);
    }
}
